// What feeds what: chains of calls where one output becomes the next input. Part of a skill
// generated by spec2skill; plain ESM for Node.js 20+, no dependencies.
import { api, operation } from './args.mjs';

/** Strongest first: `[{ ops: [id, ...], via: ["id -> projectId", ...] }]`, `via[i]` maps ops[i] into ops[i + 1]. */
export const chains = api.chains;

/** Calls that can take this call's output: `[{ to, via, confidence: "exact" | "inferred" }]`. */
export const nextSteps = (id) => operation(id).next;

/** Calls whose output can feed this call's inputs. */
export const sources = (id) =>
  api.operations.flatMap((op) => op.next.filter((n) => n.to === operation(id).id).map((n) => ({ from: op.id, via: n.via, confidence: n.confidence })));
